@startuml

class Aircraft {
  + name : string
  + type : string
  + yearOfManufacture : int
  + nextInspectionDate : date
}

class PassengerAircraft extends Aircraft {
  + numberOfSeats : int
}

class SeatCategory {
  + designation : string
  + offersEntertainment : boolean
  + numberOfSeats : int
}

class Flight {
  + flightNumber : string
  + date : date
}

class Passenger {
  + name : string
  + passportNumber : string
}

class Ticket {
  + ticketNumber : string
  + price : double
  + upgradeDesired : boolean
}

class Airline {
  + name : string
}

class FlightAttendant {
  + name : string
  + dateOfEmployment : date
  + isChiefStewardess : boolean
}

class Pilot {
  + name : string
  + dateOfEmployment : date
  + license : string
}

class Airport {
  + name : string
  + address : string
  + numberOfRunways : int
}

Airline "1" -- "0..*" Aircraft : employs
Airline "1" -- "0..*" FlightAttendant : employs
Airline "1" -- "0..*" Pilot : employs

Aircraft "1" -- "0..*" Flight : performs
Aircraft "0..1" -- "1" Airport : home airport

Flight "0..*" -- "1" Airport : departure airport
Flight "0..*" -- "1" Airport : destination airport

Flight "1" -- "0..*" Ticket : includes
Passenger "1" -- "0..*" Ticket : holds
Ticket "0..*" -- "1" SeatCategory : assigned to

Passenger "1..*" -- "0..*" Flight : takes part in

Flight "1" -- "1" Pilot : captain
Flight "1" -- "1..2" Pilot : co-pilot
Flight "0..*" -- "0..*" FlightAttendant : works on

PassengerAircraft "1" -- "1..*" SeatCategory : has

@enduml

